package decision

import geniex_sdk "github.com/qualcomm/GenieX/bindings/go"

// GenerationOptions contains the supported SDK generation controls for one
// structured decision. The zero value preserves deterministic defaults: temperature
// is zero, no stop sequence or sliding-window option is set, and generated
// grammars remain host owned.
//
// GrammarPath and GrammarString are intentionally absent. Structured decision
// grammars are generated by the host, so allowing a caller to replace either
// would weaken the decision contract.
type GenerationOptions struct {
	Temperature        float32
	TopP               float32
	TopK               int32
	MinP               float32
	RepetitionPenalty  float32
	PresencePenalty    float32
	FrequencyPenalty   float32
	Seed               int32
	Stop               []string
	SlidingWindow      bool
	SlidingWindowNKeep int32
}

func (options GenerationOptions) generationConfig(maxTokens int32, grammar, runtimeID string, images []string) *geniex_sdk.GenerationConfig {
	if maxTokens <= 0 {
		maxTokens = 128
	}
	sampler := &geniex_sdk.SamplerConfig{
		Temperature:       options.Temperature,
		TopP:              options.TopP,
		TopK:              options.TopK,
		MinP:              options.MinP,
		RepetitionPenalty: options.RepetitionPenalty,
		PresencePenalty:   options.PresencePenalty,
		FrequencyPenalty:  options.FrequencyPenalty,
		Seed:              options.Seed,
	}
	if runtimeID == geniex_sdk.RuntimeLlamaCpp && grammar != "" {
		sampler.GrammarString = grammar
	}
	return &geniex_sdk.GenerationConfig{
		MaxTokens:          maxTokens,
		Stop:               append([]string(nil), options.Stop...),
		SamplerConfig:      sampler,
		ImagePaths:         append([]string(nil), images...),
		SlidingWindow:      options.SlidingWindow,
		SlidingWindowNKeep: options.SlidingWindowNKeep,
	}
}
